def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def solve():
    N_MAX = 1000  # Search bound as suggested

    for n in range(1, N_MAX + 1):
        is_valid_n = True
        for i in range(38):
            m = n + i
            s_m = sum_digits(m)

            if s_m % 11 == 0:
                # Found a case where S(n+i) is a multiple of 11
                is_valid_n = False
                # print(f"n={n}, i={i}, m={m}, S(m)={s_m} is multiple of 11. Stopping check for this n.")
                break

        if is_valid_n:
            print(f"Smallest n found: {n}")
            return n

    print(f"No such n found up to the bound {N_MAX}.")

solve()

